923	absl::Status DirectSession::Run(
924	    const RunOptions& run_options, const NamedTensorList& inputs,
925	    const std::vector<std::string>& output_names,
926	    const std::vector<std::string>& target_nodes, std::vector<Tensor>* outputs,
927	    RunMetadata* run_metadata,
928	    const thread::ThreadPoolOptions& threadpool_options) {
929	  RunScope run_scope(&active_runs_);
930	  TF_RETURN_IF_ERROR(CheckNotClosed());
931	  TF_RETURN_IF_ERROR(CheckGraphCreated("Run()"));
932	  direct_session_runs->GetCell()->IncrementBy(1);
933	
934	  // Extract the inputs names for this run of the session.
935	  std::vector<std::string> input_tensor_names;
936	  input_tensor_names.reserve(inputs.size());
937	  size_t input_size = 0;
938	  for (const auto& it : inputs) {
939	    input_tensor_names.push_back(it.first);
940	    input_size += it.second.AllocatedBytes();
941	  }
942	  metrics::RecordGraphInputTensors(input_size);
943	
944	  // Check if we already have an executor for these arguments.
945	  ExecutorsAndKeys* executors_and_keys;
946	  RunStateArgs run_state_args(run_options.debug_options());
947	  run_state_args.collective_graph_key =
948	      run_options.experimental().collective_graph_key();
949	
950	  TF_RETURN_IF_ERROR(GetOrCreateExecutors(input_tensor_names, output_names,
951	                                          target_nodes, &executors_and_keys,
952	                                          &run_state_args));
953	  {
954	    mutex_lock l(collective_graph_key_lock_);
955	    collective_graph_key_ = executors_and_keys->collective_graph_key;
956	  }
957	
958	  // Configure a call frame for the step, which we use to feed and
959	  // fetch values to and from the executors.
960	  FunctionCallFrame call_frame(executors_and_keys->input_types,
961	                               executors_and_keys->output_types);
962	  absl::InlinedVector<Tensor, 4UL> feed_args(inputs.size());
963	  for (const auto& it : inputs) {
964	    if (it.second.dtype() == DT_RESOURCE) {
965	      Tensor tensor_from_handle;
966	      TF_RETURN_IF_ERROR(
967	          ResourceHandleToInputTensor(it.second, &tensor_from_handle));
968	      feed_args[executors_and_keys->input_name_to_index[it.first]] =
969	          tensor_from_handle;
970	    } else {
971	      feed_args[executors_and_keys->input_name_to_index[it.first]] = it.second;
972	    }
973	  }
974	  const absl::Status s = call_frame.SetArgs(feed_args);
975	  if (absl::IsInternal(s)) {
976	    return absl::InvalidArgumentError(s.message());
977	  } else if (!s.ok()) {
978	    return s;
979	  }
980	
981	  const int64_t step_id = step_id_counter_.fetch_add(1);
982	
983	  if (LogMemory::IsEnabled()) {
984	    LogMemory::RecordStep(step_id, run_state_args.handle);
985	  }
986	
987	  TF_RETURN_IF_ERROR(RunInternal(step_id, run_options, &call_frame,
988	                                 executors_and_keys, run_metadata,
989	                                 threadpool_options));
990	
991	  // Receive outputs.
992	  if (outputs) {
993	    std::vector<Tensor> sorted_outputs;
994	    const absl::Status s = call_frame.ConsumeRetvals(
995	        &sorted_outputs, /* allow_dead_tensors = */ false);
996	    if (absl::IsInternal(s)) {
997	      return absl::InvalidArgumentError(s.message());
998	    } else if (!s.ok()) {
999	      return s;
1000	    }
1001	    const bool unique_outputs =
1002	        output_names.size() == executors_and_keys->output_name_to_index.size();
1003	    // first_indices[i] = j implies that j is the smallest value for which
1004	    // output_names[i] == output_names[j].
1005	    std::vector<int> first_indices;
1006	    if (!unique_outputs) {
1007	      first_indices.reserve(output_names.size());
1008	      for (const auto& name : output_names) {
1009	        first_indices.push_back(
1010	            std::find(output_names.begin(), output_names.end(), name) -
1011	            output_names.begin());
1012	      }
1013	    }
1014	    outputs->clear();
1015	    size_t output_size = 0;
1016	    outputs->reserve(sorted_outputs.size());
1017	    for (int i = 0; i < output_names.size(); ++i) {
1018	      const std::string& output_name = output_names[i];
1019	      if (first_indices.empty() || first_indices[i] == i) {
1020	        outputs->emplace_back(
1021	            std::move(sorted_outputs[executors_and_keys
1022	                                         ->output_name_to_index[output_name]]));
1023	      } else {
1024	        outputs->push_back((*outputs)[first_indices[i]]);
1025	      }
1026	      output_size += outputs->back().AllocatedBytes();
1027	    }
1028	    metrics::RecordGraphOutputTensors(output_size);
1029	  }
1030	
1031	  return absl::OkStatus();
1032	}
1033	
1034	absl::Status DirectSession::PRunSetup(
1035	    const std::vector<std::string>& input_names,
1036	    const std::vector<std::string>& output_names,
1037	    const std::vector<std::string>& target_nodes, std::string* handle) {
1038	  RunScope run_scope(&active_runs_);
1039	  TF_RETURN_IF_ERROR(CheckNotClosed());
1040	  TF_RETURN_IF_ERROR(CheckGraphCreated("PRunSetup()"));
1041	
1042	  // RunOptions is not available in PRunSetup, so use thread pool 0.
1043	  thread::ThreadPool* pool = thread_pools_[0].first;
1044	
1045	  // Check if we already have an executor for these arguments.
1046	  ExecutorsAndKeys* executors_and_keys;
1047	  // TODO(cais): TFDBG support for partial runs.
1048	  DebugOptions debug_options;
1049	  RunStateArgs run_state_args(debug_options);
1050	  run_state_args.is_partial_run = true;
1051	  TF_RETURN_IF_ERROR(GetOrCreateExecutors(input_names, output_names,
1052	                                          target_nodes, &executors_and_keys,
1053	                                          &run_state_args));
1054	
1055	  // Create the run state and save it for future PRun calls.
1056	  Executor::Args args;
1057	  args.step_id = step_id_counter_.fetch_add(1);
1058	  PartialRunState* run_state =
1059	      new PartialRunState(input_names, output_names, args.step_id, &devices_);
1060	  run_state->rendez.reset(new IntraProcessRendezvous(device_mgr_.get()));
1061	  {
1062	    mutex_lock l(executor_lock_);
1063	    if (!partial_runs_
1064	             .emplace(run_state_args.handle,
1065	                      std::unique_ptr<PartialRunState>(run_state))
1066	             .second) {
1067	      return absl::InternalError(
1068	          absl::StrCat("The handle '", run_state_args.handle,
1069	                       "' created for this partial run is not unique."));
1070	    }
1071	  }
