578	absl::Status DirectSession::RunInternal(
579	    int64_t step_id, const RunOptions& run_options,
580	    CallFrameInterface* call_frame, ExecutorsAndKeys* executors_and_keys,
581	    RunMetadata* run_metadata,
582	    const thread::ThreadPoolOptions& threadpool_options) {
583	  const uint64_t start_time_usecs = options_.env->NowMicros();
584	  const int64_t executor_step_count =
585	      executors_and_keys->step_count.fetch_add(1);
586	  RunState run_state(step_id, &devices_);
587	  const size_t num_executors = executors_and_keys->items.size();
588	
589	  tsl::profiler::TraceMeProducer activity(
590	      // To TraceMeConsumers in ExecutorState::Process/Finish.
591	      [&] {
592	        if (options_.config.experimental().has_session_metadata()) {
593	          const auto& model_metadata =
594	              options_.config.experimental().session_metadata();
595	          std::string model_id = absl::StrCat(model_metadata.name(), ":",
596	                                              model_metadata.version());
597	          return tsl::profiler::TraceMeEncode("SessionRun",
598	                                              {{"id", step_id},
599	                                               {"_r", 1} /*root_event*/,
600	                                               {"model_id", model_id}});
601	        } else {
602	          return tsl::profiler::TraceMeEncode(
603	              "SessionRun", {{"id", step_id}, {"_r", 1} /*root_event*/});
604	        }
605	      },
606	      tsl::profiler::ContextType::kTfExecutor, step_id,
607	      tsl::profiler::TraceMeLevel::kInfo);
608	
609	  std::unique_ptr<DebuggerStateInterface> debugger_state;
610	  if (!run_options.debug_options().debug_tensor_watch_opts().empty()) {
611	    TF_RETURN_IF_ERROR(
612	        CreateDebuggerState(executors_and_keys->callable_options,
613	                            run_options.debug_options().global_step(), step_id,
614	                            executor_step_count, &debugger_state));
615	  }
616	
617	  if (run_metadata != nullptr &&
618	      options_.config.experimental().has_session_metadata()) {
619	    *run_metadata->mutable_session_metadata() =
620	        options_.config.experimental().session_metadata();
621	  }
622	
623	#ifndef __ANDROID__
624	  // Set up for collectives if ExecutorsAndKeys declares a key.
625	  if (executors_and_keys->collective_graph_key !=
626	      BuildGraphOptions::kNoCollectiveGraphKey) {
627	    if (run_options.experimental().collective_graph_key() !=
628	        BuildGraphOptions::kNoCollectiveGraphKey) {
629	      // If a collective_graph_key was specified in run_options, ensure that it
630	      // matches what came out of GraphExecutionState::BuildGraph().
631	      if (run_options.experimental().collective_graph_key() !=
632	          executors_and_keys->collective_graph_key) {
633	        return absl::InternalError(absl::StrCat(
634	            "collective_graph_key in RunOptions ",
635	            run_options.experimental().collective_graph_key(),
636	            " should match collective_graph_key from optimized graph ",
637	            executors_and_keys->collective_graph_key));
638	      }
639	    }
640	    if (!collective_executor_mgr_) {
641	      collective_executor_mgr_ = CreateProdLocalCollectiveExecutorMgr(
642	          options_.config, device_mgr_.get(),
643	          MaybeCreateNcclCommunicator(options_.config));
644	    }
645	    run_state.collective_executor.reset(new CollectiveExecutor::Handle(
646	        collective_executor_mgr_->FindOrCreate(step_id), true /*inherit_ref*/));
647	  }
648	#endif
649	
650	  thread::ThreadPool* pool;
651	  // Use std::unique_ptr to ensure garbage collection
652	  std::unique_ptr<thread::ThreadPool> threadpool_wrapper;
653	
654	  const bool inline_execution_requested =
655	      run_in_caller_thread_ || run_options.inter_op_thread_pool() == -1;
656	
657	  if (inline_execution_requested) {
658	    // We allow using the caller thread only when having a single executor
659	    // specified.
660	    if (executors_and_keys->items.size() > 1) {
661	      pool = thread_pools_[0].first;
662	    } else {
663	      VLOG(1) << "Executing Session::Run() synchronously!";
664	      pool = nullptr;
665	    }
666	  } else if (threadpool_options.inter_op_threadpool != nullptr) {
667	    threadpool_wrapper = std::make_unique<thread::ThreadPool>(
668	        threadpool_options.inter_op_threadpool);
669	    pool = threadpool_wrapper.get();
670	  } else {
671	    if (run_options.inter_op_thread_pool() < -1 ||
672	        run_options.inter_op_thread_pool() >=
673	            static_cast<int32_t>(thread_pools_.size())) {
674	      return absl::InvalidArgumentError(
675	          absl::StrCat("Invalid inter_op_thread_pool: ",
676	                       run_options.inter_op_thread_pool()));
677	    }
678	
679	    pool = thread_pools_[run_options.inter_op_thread_pool()].first;
680	  }
681	
682	  const int64_t call_timeout = run_options.timeout_in_ms() > 0
683	                                   ? run_options.timeout_in_ms()
684	                                   : operation_timeout_in_ms_;
685	  absl::optional<absl::Time> deadline;
686	  if (call_timeout > 0) {
687	    deadline = absl::Now() + absl::Milliseconds(call_timeout);
688	  }
689	
690	  std::unique_ptr<RunHandler> handler;
691	  if (ShouldUseRunHandlerPool(run_options) &&
692	      run_options.experimental().use_run_handler_pool()) {
693	    VLOG(1) << "Using RunHandler to scheduler inter-op closures.";
694	    handler = GetOrCreateRunHandlerPool(options_)->Get(
695	        step_id, call_timeout,
696	        run_options.experimental().run_handler_pool_options());
697	    if (!handler) {
698	      return absl::DeadlineExceededError(absl::StrCat(
699	          "Could not obtain RunHandler for request after waiting for ",
700	          call_timeout, "ms."));
701	    }
702	  }
703	  auto* handler_ptr = handler.get();
704	
705	  Executor::Args::Runner default_runner = nullptr;
706	
707	  if (pool == nullptr) {
708	    default_runner = [](const Executor::Args::Closure& c) { c(); };
709	  } else if (handler_ptr != nullptr) {
710	    default_runner = [handler_ptr](Executor::Args::Closure c) {
711	      handler_ptr->ScheduleInterOpClosure(std::move(c));
712	    };
713	  } else {
714	    default_runner = [pool](Executor::Args::Closure c) {
715	      pool->Schedule(std::move(c));
716	    };
717	  }
718	
719	  // Start parallel Executors.
720	
721	  // We can execute this step synchronously on the calling thread whenever
722	  // there is a single device and the timeout mechanism is not used.
723	  //
724	  // When timeouts are used, we must execute the graph(s) asynchronously, in
725	  // order to invoke the cancellation manager on the calling thread if the
726	  // timeout expires.
727	  const bool can_execute_synchronously =
728	      executors_and_keys->items.size() == 1 && call_timeout == 0;
729	
730	  Executor::Args args;
731	  args.step_id = step_id;
732	  args.call_frame = call_frame;
733	  args.collective_executor =
734	      (run_state.collective_executor ? run_state.collective_executor->get()
735	                                     : nullptr);
736	  args.session_config = &options_.config;
737	  args.session_state = &session_state_;
738	  args.session_handle = session_handle_;
739	  args.tensor_store = &run_state.tensor_store;
740	  args.step_container = &run_state.step_container;
741	  args.sync_on_finish = sync_on_finish_;
742	  args.user_intra_op_threadpool = threadpool_options.intra_op_threadpool;
743	  args.run_all_kernels_inline = pool == nullptr;
744	  args.start_time_usecs = start_time_usecs;
745	  args.deadline = deadline;
746	
747	  const bool do_trace = (run_options.trace_level() > RunOptions::NO_TRACE);
748	
749	  bool update_cost_model = false;
750	  if (options_.config.graph_options().build_cost_model() > 0) {
751	    const int64_t build_cost_model_every =
752	        options_.config.graph_options().build_cost_model();
753	    const int64_t build_cost_model_after =
754	        options_.config.graph_options().build_cost_model_after();
755	    int64_t measure_step_count = executor_step_count - build_cost_model_after;
756	    if (measure_step_count >= 0) {
757	      update_cost_model =
758	          ((measure_step_count + 1) % build_cost_model_every == 0);
759	    }
760	  }
761	  if (run_metadata != nullptr &&
762	      (do_trace || update_cost_model ||
763	       run_options.report_tensor_allocations_upon_oom())) {
764	    run_state.collector.reset(
765	        new StepStatsCollector(run_metadata->mutable_step_stats()));
766	    args.stats_collector = run_state.collector.get();
767	  }
768	
769	  std::unique_ptr<DeviceProfilerSession> device_profiler_session;
770	  if (run_options.trace_level() >= RunOptions::HARDWARE_TRACE) {
771	    device_profiler_session = DeviceProfilerSession::Create();
772	  }
773	
774	  // Register this step with session's cancellation manager, so that
775	  // `Session::Close()` will cancel the step.
776	  CancellationManager step_cancellation_manager(cancellation_manager_);
777	  if (step_cancellation_manager.IsCancelled()) {
778	    return absl::CancelledError("Run call was cancelled");
779	  }
780	  args.cancellation_manager = &step_cancellation_manager;
781	
782	  absl::Status run_status;
783	
784	  auto set_threadpool_args_for_item =
785	      [&default_runner, &handler](const PerPartitionExecutorsAndLib& item,
786	                                  Executor::Args* args) {
787	        // TODO(azaks): support partial run.
788	        // TODO(azaks): if the device picks its own threadpool, we need to
789	        // assign
790	        //     less threads to the main compute pool by default.
791	        thread::ThreadPool* device_thread_pool =
792	            item.device->tensorflow_device_thread_pool();
793	        // TODO(crk): Investigate usage of RunHandlerPool when using device
794	        // specific thread pool(s).
795	        if (!device_thread_pool) {
796	          args->runner = default_runner;
797	        } else {
798	          args->runner = [device_thread_pool](Executor::Args::Closure c) {
799	            device_thread_pool->Schedule(std::move(c));
800	          };
801	        }
802	        if (handler != nullptr) {
803	          args->user_intra_op_threadpool =
804	              handler->AsIntraThreadPoolInterface();
805	        }
806	      };
807	
808	  if (can_execute_synchronously) {
809	    PrivateIntraProcessRendezvous rendezvous(device_mgr_.get());
810	    args.rendezvous = &rendezvous;
811	
812	    const auto& item = executors_and_keys->items[0];
813	    set_threadpool_args_for_item(item, &args);
814	    run_status = item.executor->Run(args);
815	  } else {
816	    core::RefCountPtr<RefCountedIntraProcessRendezvous> rendezvous(
817	        new RefCountedIntraProcessRendezvous(device_mgr_.get()));
818	    args.rendezvous = rendezvous.get();
819	
820	    // `barrier` will delete itself after the final executor finishes.
821	    absl::Notification executors_done;
822	    ExecutorBarrier* barrier = new ExecutorBarrier(
823	        num_executors, rendezvous.get(),
824	        [&run_state, &executors_done](const absl::Status& ret) {
825	          {
826	            mutex_lock l(run_state.mu);
827	            run_state.status.Update(ret);
828	          }
829	          executors_done.Notify();
830	        });
831	
832	    for (const auto& item : executors_and_keys->items) {
833	      set_threadpool_args_for_item(item, &args);
834	      item.executor->RunAsync(args, barrier->Get());
835	    }
836	
837	    WaitForNotification(&executors_done, &run_state, &step_cancellation_manager,
838	                        call_timeout);
839	    {
840	      tf_shared_lock l(run_state.mu);
841	      run_status = run_state.status;
842	    }
843	  }
844	
845	  if (step_cancellation_manager.IsCancelled()) {
846	    run_status.Update(absl::CancelledError("Run call was cancelled"));
847	  }
848	
849	  if (run_metadata != nullptr && device_profiler_session) {
850	    TF_RETURN_IF_ERROR(device_profiler_session->CollectData(
851	        run_metadata->mutable_step_stats()));
852	  }
853	
854	  TF_RETURN_IF_ERROR(run_status);
855	
856	  // Save the output tensors of this run we choose to keep.
857	  if (!run_state.tensor_store.empty()) {
858	    TF_RETURN_IF_ERROR(run_state.tensor_store.SaveTensors(
859	        {executors_and_keys->callable_options.fetch().begin(),
860	         executors_and_keys->callable_options.fetch().end()},
861	        &session_state_));
862	  }
863	
864	  if (run_state.collector) {
865	    run_state.collector->Finalize();
866	  }
867	
868	  // Build and return the cost model as instructed.
869	  if (update_cost_model) {
870	    // Build the cost model
871	    std::unordered_map<std::string, const Graph*> device_to_graph;
872	    for (const PerPartitionExecutorsAndLib& partition :
873	         executors_and_keys->items) {
874	      const Graph* graph = partition.graph.get();
875	      const std::string& device = partition.flib->device()->name();
876	      device_to_graph[device] = graph;
877	    }
878	
879	    mutex_lock l(executor_lock_);
880	    run_state.collector->BuildCostModel(&cost_model_manager_, device_to_graph);
881	
882	    if (run_metadata != nullptr) {
883	      // annotate stats onto cost graph.
884	      CostGraphDef* cost_graph = run_metadata->mutable_cost_graph();
885	      for (const auto& item : executors_and_keys->items) {
886	        TF_RETURN_IF_ERROR(cost_model_manager_.AddToCostGraphDef(
887	            item.graph.get(), cost_graph));
888	      }
889	    }
890	  }
891	
892	  // If requested via RunOptions, output the partition graphs.
893	  if (run_options.output_partition_graphs()) {
894	    if (options_.config.experimental().disable_output_partition_graphs()) {
895	      return absl::InvalidArgumentError(
896	          "RunOptions.output_partition_graphs() is not supported when "
897	          "disable_output_partition_graphs is true.");
898	    } else if (run_metadata != nullptr) {
899	      protobuf::RepeatedPtrField<GraphDef>* partition_graph_defs =
900	          run_metadata->mutable_partition_graphs();
901	      for (const PerPartitionExecutorsAndLib& exec_and_lib :
902	           executors_and_keys->items) {
903	        GraphDef* partition_graph_def = partition_graph_defs->Add();
904	        exec_and_lib.graph->ToGraphDef(partition_graph_def);
905	      }
906	    }
907	  }
908	  metrics::UpdateGraphExecTime(options_.env->NowMicros() - start_time_usecs);
909	
910	  return absl::OkStatus();
911	}
